import { Injectable, inject } from '@angular/core';
import { SupabaseClient } from '@supabase/supabase-js';
import { BehaviorSubject, from, map, shareReplay, switchMap } from 'rxjs';
import { Profile } from 'src/app/profile/profile';
import { Database } from 'supabase/types/supabase';
import { UserService } from '../common/user/user.service';

@Injectable({
  providedIn: 'root',
})
export class ProfileService {
  private readonly userService = inject(UserService);
  private readonly supabaseClient = inject<SupabaseClient<Database>>(SupabaseClient);

  private refreshProfile$ = new BehaviorSubject<void>(undefined);

  get profile$() {
    return this.refreshProfile$.pipe(
      switchMap(async () => this.getProfile()),
      map((profile) => profile.data),
      shareReplay(1)
    );
  }

  get isAdmin$() {
    return from(this.checkAdminFromAuth()).pipe(
      shareReplay(1)
    );
  }

  private async checkAdminFromAuth(): Promise<boolean> {
    const user = await this.userService.getUser();

    if (!user) {
      return false;
    }

    // Check admin status from secure auth metadata (only modifiable by service role)
    return user.app_metadata?.['is_admin'] === true;
  }

  async getProfile() {
    const user = await this.userService.getUser();

    if (!user) {
      throw new Error('User not found');
    }

    if (!user.id) {
      throw new Error('User ID not found');
    }

    return this.supabaseClient
      .from('profiles')
      .select(`*`)
      .eq('id', user.id)
      .single();
  }

  async updateProfile(profile: Profile) {
    const user = await this.userService.getUser();

    if (!user) {
      throw new Error('User not found');
    }

    if (!user.id) {
      throw new Error('User ID not found');
    }

    const update = {
      ...profile,
      id: user.id,
      updated_at: new Date().toISOString(),
    };

    const result = await this.supabaseClient.from('profiles').upsert(update);

    this.refreshProfile$.next();

    return result;
  }
}
